def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    def components(color):
        found = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        p = (y + dy, x + dx)
                        if (0 <= p[0] < h and 0 <= p[1] < w
                                and grid[p[0]][p[1]] == color and p not in seen):
                            seen.add(p)
                            stack.append(p)
                found.append(cells)
        return found

    def shape(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    others = []
    for color in range(1, 10):
        if color == 1:
            continue
        for cells in components(color):
            others.append((color, cells))

    ones = components(1)
    for cells in ones:
        s = shape(cells)
        exact = [color for color, other in others if shape(other) == s]
        if exact:
            color = exact[0]
        else:
            same_size = [color for color, other in others if len(other) == len(cells)]
            if not same_size:
                continue
            color = same_size[0]
        for r, c in cells:
            out[r][c] = color

    return out
